// src/components/PlanningFinal.jsx
import { useState, useEffect } from "react";
import { soutenanceApi } from "../api/api";

const STATUT_STYLE = {
  PLANIFIEE: { label: "Planifiée", bg: "#EFF6FF", color: "#1D4ED8", border: "#3B82F6" },
  TERMINEE:  { label: "Terminée",  bg: "#F0FDF4", color: "#166534", border: "#22C55E" },
  ANNULEE:   { label: "Annulée",   bg: "#FEF2F2", color: "#991B1B", border: "#EF4444" },
  EN_COURS:  { label: "En cours",  bg: "#FFFBEB", color: "#92400E", border: "#F59E0B" },
};

function StatutBadge({ statut }) {
  const s = STATUT_STYLE[statut] || STATUT_STYLE.PLANIFIEE;
  return (
    <span style={{ background: s.bg, color: s.color, border: `1px solid ${s.border}`, padding: "3px 10px", borderRadius: 12, fontSize: 12, fontWeight: 600 }}>
      {s.label}
    </span>
  );
}

export default function PlanningFinal() {
  const [soutenances, setSoutenances] = useState([]);
  const [loading, setLoading]         = useState(true);
  const [search, setSearch]           = useState("");
  const [selectedDate, setSelectedDate] = useState("");
  const [resultat, setResultat]       = useState({});
  const [showForm, setShowForm]       = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const data = selectedDate
        ? await soutenanceApi.getPlanningParDate(selectedDate)
        : await soutenanceApi.getPlanningFinal();
      setSoutenances(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [selectedDate]);

  const handlePlanifierAuto = async () => {
    if (!window.confirm("Lancer la planification automatique ?")) return;
    try {
      const res = await soutenanceApi.planifierAuto();
      alert(`${res.length} soutenance(s) planifiée(s).`);
      load();
    } catch (e) { alert(e.message); }
  };

  const handleResultat = async (id) => {
    const r = resultat[id];
    if (!r?.note) { alert("Note obligatoire."); return; }
    try {
      await soutenanceApi.enregistrerResultat(id, {
        note: parseFloat(r.note),
        observations: r.observations || "",
        present: r.present !== false,
      });
      setShowForm(null);
      load();
    } catch (e) { alert(e.message); }
  };

  const filtered = soutenances.filter(s => {
    const q = search.toLowerCase();
    return (
      s.binome?.etudiant1?.nom?.toLowerCase().includes(q) ||
      s.binome?.etudiant2?.nom?.toLowerCase().includes(q) ||
      s.affectation?.sujet?.titre?.toLowerCase().includes(q) ||
      s.creneau?.salle?.toLowerCase().includes(q)
    );
  });

  const counts = {
    total:    soutenances.length,
    planif:   soutenances.filter(s => s.statut === "PLANIFIEE").length,
    terminees:soutenances.filter(s => s.statut === "TERMINEE").length,
    moyenne:  soutenances.filter(s => s.note).reduce((acc, s, _, arr) =>
                acc + s.note / arr.filter(x => x.note).length, 0),
  };

  return (
    <div style={styles.page}>
      <h2 style={styles.title}>Phase 4 — Planning final des soutenances</h2>

      {/* Métriques */}
      <div style={styles.metrics}>
        {[
          { label: "Total",      val: counts.total,     color: "#6366F1" },
          { label: "Planifiées", val: counts.planif,    color: "#3B82F6" },
          { label: "Terminées",  val: counts.terminees, color: "#10B981" },
          { label: "Moy. générale", val: counts.moyenne ? counts.moyenne.toFixed(1) : "—", color: "#F59E0B" },
        ].map(m => (
          <div key={m.label} style={styles.metric}>
            <div style={{ fontSize: 26, fontWeight: 700, color: m.color }}>{m.val}</div>
            <div style={{ fontSize: 12, color: "#6B7280" }}>{m.label}</div>
          </div>
        ))}
      </div>

      {/* Barre d'outils */}
      <div style={styles.toolbar}>
        <input
          placeholder="Rechercher binôme, sujet, salle..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={styles.search}
        />
        <input type="date" value={selectedDate}
          onChange={e => setSelectedDate(e.target.value)}
          style={styles.datePicker}
        />
        {selectedDate && (
          <button onClick={() => setSelectedDate("")} style={styles.btnClear}>✕ Tout</button>
        )}
        <button onClick={handlePlanifierAuto} style={styles.btnAuto}>
          Planification auto
        </button>
      </div>

      {loading && <div style={styles.center}>Chargement...</div>}

      {!loading && filtered.length === 0 && (
        <div style={styles.empty}>Aucune soutenance trouvée.</div>
      )}

      {filtered.map(s => (
        <div key={s.id} style={styles.card}>
          <div style={styles.cardHeader}>
            <div>
              <div style={styles.cardTitle}>
                {s.binome?.etudiant1?.nom} & {s.binome?.etudiant2?.nom}
              </div>
              <div style={styles.cardSub}>{s.affectation?.sujet?.titre}</div>
            </div>
            <StatutBadge statut={s.statut} />
          </div>

          <div style={styles.grid}>
            <InfoRow label="Encadrant" val={s.affectation?.sujet?.encadrant?.nom} />
            <InfoRow label="Jury"      val={s.jury?.map(j => j.nom).join(", ") || "—"} />
            <InfoRow label="Date"      val={s.creneau?.date} />
            <InfoRow label="Heure"     val={`${s.creneau?.heureDebut} → ${s.creneau?.heureFin}`} />
            <InfoRow label="Salle"     val={s.creneau?.salle} />
            <InfoRow label="Note"      val={s.note != null ? `${s.note} / 20` : "—"} />
            <InfoRow label="Présence"  val={s.present == null ? "—" : s.present ? "Présent" : "Absent"} />
          </div>

          {s.observations && (
            <div style={styles.obs}>Observations : {s.observations}</div>
          )}

          {/* Formulaire résultat */}
          {s.statut === "PLANIFIEE" && (
            <div style={{ marginTop: 12 }}>
              {showForm === s.id ? (
                <div style={styles.form}>
                  <input type="number" min="0" max="20" step="0.5"
                    placeholder="Note /20"
                    value={resultat[s.id]?.note || ""}
                    onChange={e => setResultat(p => ({ ...p, [s.id]: { ...p[s.id], note: e.target.value } }))}
                    style={{ ...styles.input, width: 90 }}
                  />
                  <input placeholder="Observations"
                    value={resultat[s.id]?.observations || ""}
                    onChange={e => setResultat(p => ({ ...p, [s.id]: { ...p[s.id], observations: e.target.value } }))}
                    style={{ ...styles.input, flex: 1 }}
                  />
                  <label style={{ fontSize: 13, display: "flex", alignItems: "center", gap: 4 }}>
                    <input type="checkbox" defaultChecked
                      onChange={e => setResultat(p => ({ ...p, [s.id]: { ...p[s.id], present: e.target.checked } }))}
                    /> Présent
                  </label>
                  <button onClick={() => handleResultat(s.id)} style={styles.btnSave}>Enregistrer</button>
                  <button onClick={() => setShowForm(null)} style={styles.btnCancel}>Annuler</button>
                </div>
              ) : (
                <button onClick={() => setShowForm(s.id)} style={styles.btnResult}>
                  Enregistrer résultat
                </button>
              )}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

function InfoRow({ label, val }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", padding: "5px 0",
      borderTop: "1px solid #F3F4F6", fontSize: 13 }}>
      <span style={{ color: "#6B7280" }}>{label}</span>
      <span style={{ fontWeight: 500, color: "#111827" }}>{val || "—"}</span>
    </div>
  );
}

const styles = {
  page:      { maxWidth: 860, margin: "0 auto", padding: "24px 16px", fontFamily: "sans-serif" },
  title:     { fontSize: 22, fontWeight: 700, color: "#111827", marginBottom: 20 },
  center:    { textAlign: "center", padding: 40, color: "#6B7280" },
  empty:     { textAlign: "center", padding: 40, color: "#9CA3AF" },
  metrics:   { display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12, marginBottom: 20 },
  metric:    { background: "#F9FAFB", border: "1px solid #E5E7EB", borderRadius: 10, padding: "14px 16px", textAlign: "center" },
  toolbar:   { display: "flex", gap: 8, marginBottom: 20, flexWrap: "wrap", alignItems: "center" },
  search:    { flex: 1, minWidth: 200, padding: "8px 12px", borderRadius: 8, border: "1px solid #D1D5DB", fontSize: 13 },
  datePicker:{ padding: "8px 12px", borderRadius: 8, border: "1px solid #D1D5DB", fontSize: 13 },
  btnClear:  { padding: "8px 12px", borderRadius: 8, border: "1px solid #D1D5DB", background: "#fff", cursor: "pointer", fontSize: 13 },
  btnAuto:   { padding: "8px 16px", borderRadius: 8, border: "none", background: "#6366F1", color: "#fff", cursor: "pointer", fontWeight: 600 },
  card:      { background: "#fff", border: "1px solid #E5E7EB", borderRadius: 12, padding: "16px 20px", marginBottom: 12 },
  cardHeader:{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 },
  cardTitle: { fontSize: 15, fontWeight: 600, color: "#111827" },
  cardSub:   { fontSize: 13, color: "#6B7280", marginTop: 2 },
  grid:      { display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 24px" },
  obs:       { marginTop: 8, padding: "8px 12px", background: "#F9FAFB", borderRadius: 8, fontSize: 13, color: "#374151" },
  form:      { display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" },
  input:     { padding: "7px 10px", borderRadius: 8, border: "1px solid #D1D5DB", fontSize: 13 },
  btnSave:   { padding: "7px 14px", borderRadius: 8, border: "none", background: "#10B981", color: "#fff", cursor: "pointer", fontWeight: 600 },
  btnCancel: { padding: "7px 14px", borderRadius: 8, border: "1px solid #D1D5DB", background: "#fff", cursor: "pointer" },
  btnResult: { padding: "7px 14px", borderRadius: 8, border: "1px solid #6366F1", color: "#6366F1", background: "#fff", cursor: "pointer", fontWeight: 600 },
};
